<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{Upgrade,Database,Authorization,Audit};
/** Module adapter using the existing Shared Core ledger, conflict checks and lock. */
final class Migrations {
 public static function files():array {$f=glob(APP_ROOT.'/database/modules/eforms/*.{sql,php}',GLOB_BRACE);sort($f);return $f;}
 public static function plan(\PDO $p):array {if(!Upgrade::ready($p)||!is_file(APP_ROOT.'/storage/installed.lock'))throw new \RuntimeException('Shared Core mesti lengkap dan installer dikunci.');$out=[];foreach(self::files() as $f){$version='eforms:Phase2:'.basename($f);$r=Database::query($p,'SELECT checksum,status FROM database_migrations WHERE version=?',[$version])->fetch();if($r&&($r['status']!=='applied'||!hash_equals($r['checksum'],hash_file('sha256',$f))))throw new \RuntimeException('Migration/checksum e-Forms bercanggah.');if(!$r&&str_ends_with($f,'.sql')&&Upgrade::conflicts($p,file_get_contents($f)))throw new \RuntimeException('Untracked schema e-Forms; hentikan pemasangan.');$out[]=['version'=>$version,'status'=>$r?'applied':'pending'];}return $out;}
 public static function apply(\PDO $p,int $actor):void {if(!Authorization::super($p,$actor))throw new \RuntimeException('Super Admin diperlukan.');if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_upgrade_',LEFT(SHA2(DATABASE(),256),40)),5)")->fetchColumn()!==1)throw new \RuntimeException('Upgrade sedang berjalan.');try{self::plan($p);foreach(self::files() as $f){$v='eforms:Phase2:'.basename($f);if(Database::query($p,'SELECT 1 FROM database_migrations WHERE version=?',[$v])->fetchColumn())continue;Database::query($p,"INSERT INTO database_migrations(version,checksum,status) VALUES(?,?,'started')",[$v,hash_file('sha256',$f)]);try{if(str_ends_with($f,'.sql'))$p->exec(file_get_contents($f));else ($fn=require $f)($p);Database::query($p,"UPDATE database_migrations SET status='applied',applied_at=UTC_TIMESTAMP() WHERE version=?",[$v]);}catch(\Throwable $e){throw new \RuntimeException('Migration separa gagal. Hentikan dan pulihkan daripada backup; jangan ulang DDL.',0,$e);}}Audit::record($p,'eforms.migrated',$actor,null,'1.3.0','eforms','Backup-confirmed module migration');}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_upgrade_',LEFT(SHA2(DATABASE(),256),40)))");}}
}
